//! The AUTOGENERATED marker that identifies files owned by the generator (spec §5).

use crate::GENERATOR_VERSION;

pub const MARKER_TEXT: &str = "AUTOGENERATED by shader-editor v";

/// Whether a file's first line carries the AUTOGENERATED marker (`//` or `#` comment).
pub fn has_marker(text: &str) -> bool {
    let first = text.lines().next().unwrap_or("");
    let body = first.trim_start_matches("//").trim_start_matches('#').trim_start();
    body.starts_with(MARKER_TEXT) && first.contains("do not edit")
}

/// Header line `{comment} AUTOGENERATED by shader-editor v1 from {source} — do not edit`.
pub fn header(comment: &str, source: Option<&str>) -> String {
    match source {
        Some(s) => format!("{comment} {MARKER_TEXT}{GENERATOR_VERSION} from {s} — do not edit"),
        None => format!("{comment} {MARKER_TEXT}{GENERATOR_VERSION} — do not edit"),
    }
}

/// Inserts a `// generated: {date}` line after the header.
pub fn insert_date(text: &mut String, date: &str) {
    if let Some(pos) = text.find('\n') {
        text.insert_str(pos + 1, &format!("// generated: {date}\n"));
    }
}

/// Today's UTC date as `YYYY-MM-DD`.
pub fn civil_today() -> String {
    let secs = std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).map(|d| d.as_secs()).unwrap_or(0);
    let z = (secs / 86400) as i64 + 719_468;
    let era = z.div_euclid(146_097);
    let doe = z - era * 146_097;
    let yoe = (doe - doe / 1460 + doe / 36_524 - doe / 146_096) / 365;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let d = doy - (153 * mp + 2) / 5 + 1;
    let m = if mp < 10 { mp + 3 } else { mp - 9 };
    let y = yoe + era * 400 + i64::from(m <= 2);
    format!("{y:04}-{m:02}-{d:02}")
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn header_has_marker() {
        assert!(has_marker(&header("//", Some("quillshade/material/a.material.ron"))));
        assert!(has_marker(&header("#", None)));
        assert_eq!(header("//", Some("a.ron")), "// AUTOGENERATED by shader-editor v1 from a.ron — do not edit");
        assert!(!has_marker("// hand written"));
    }

    #[test]
    fn date_goes_after_header() {
        let mut t = format!("{}\nbody\n", header("//", None));
        insert_date(&mut t, "2026-01-02");
        assert_eq!(t.lines().nth(1), Some("// generated: 2026-01-02"));
        assert_eq!(civil_today().len(), 10);
    }
}
